"""Execute JS and verify case/time/view controls in a real headless browser."""
import sys,html,json,re,subprocess,tempfile
from pathlib import Path
page=Path(sys.argv[1]).resolve();out=page.parent
script="""<script>try{let checks={rendered:document.body.dataset.rendered==='true',cases:Object.keys(data).length>0};let before=by('map').toDataURL();by('time').value=5;by('time').dispatchEvent(new Event('input'));checks.time_changes=before!==by('map').toDataURL();before=by('map').toDataURL();by('profile').value=9;by('profile').dispatchEvent(new Event('change'));checks.profile_changes=before!==by('map').toDataURL();before=by('map').toDataURL();by('layer').value='nav2';by('layer').dispatchEvent(new Event('change'));checks.nav2_layer_changes=before!==by('map').toDataURL();by('layer').value='terrain';by('layer').dispatchEvent(new Event('change'));if(Object.keys(data).length>1){before=by('map').toDataURL();by('case').selectedIndex=1;by('case').dispatchEvent(new Event('change'));checks.case_changes=before!==by('map').toDataURL();}checks.passed=Object.values(checks).every(Boolean);let p=document.createElement('pre');p.id='qa';p.textContent=JSON.stringify(checks);document.body.append(p);}catch(e){let p=document.createElement('pre');p.id='qa';p.textContent=JSON.stringify({passed:false,error:String(e)});document.body.append(p);}</script>"""
with tempfile.TemporaryDirectory(prefix='s09_browser_') as tmp:
    p=out/'_qa.html';p.write_text(page.read_text().replace('</html>',script+'</html>'));args=['google-chrome','--headless','--disable-gpu','--no-first-run','--no-default-browser-check',f'--user-data-dir={tmp}/profile','--virtual-time-budget=3000','--window-size=1480,1200',f'--screenshot={out}/report_preview.png','--dump-dom',p.as_uri()];r=subprocess.run(args,capture_output=True,text=True,timeout=40);m=re.search('<pre id="qa">(.*?)</pre>',r.stdout);result=json.loads(html.unescape(m.group(1))) if m else dict(passed=False,error='QA DOM missing');result.update(exit_code=r.returncode,command=args);(out/'browser_check.json').write_text(json.dumps(result,indent=2)+'\n');p.unlink(missing_ok=True);print(json.dumps(result));raise SystemExit(0 if result['passed'] and r.returncode==0 else 1)
